const j = $input.first().json;
const bin = $input.first().binary;

if (!bin) throw new Error('Файл не приложен');

const keys = Object.keys(bin);
if (keys.length === 0) throw new Error('Бинарных полей нет');

const empId = Number(j['ID сотрудника']);
if (!empId) throw new Error('Не указан ID сотрудника. Поля: ' + Object.keys(j).join(', '));

// кладём файл под фиксированным именем
const out = {};
out['gb'] = bin[keys[0]];

return [{
  json: { employee_id: empId, binary_name_was: keys[0] },
  binary: out
}];

const rows = $input.all().map(i => i.json);
if (rows.length === 0) throw new Error('Лист пустой или не найден');

return [{ json: {
  headers_text: Object.keys(rows[0]).join(' | '),
  row_count:    rows.length,
  rows:         rows
}}];

// ↓↓↓ ТОЛЬКО ЭТИ ЧЕТЫРЕ СТРОКИ РАЗЛИЧАЮТСЯ МЕЖДУ ВЕТКАМИ ↓↓↓
const PREV_NODE = 'Н2. Заголовки';
const SHEET     = 'навыки';
const REQUIRED  = 'skill_name';
const ALLOWED   = ['specialty','knowledge_area','competency','competency_description',
                   'skill_name','skill_type','skill_description',
                   'development_indicators','success_criteria'];
// ↑↑↑

const j = $input.first().json;
let raw = '';

// текст лежит в choices[0].message.content
try { raw = String(j.choices[0].message.content || ''); } catch (e) { raw = ''; }

// запасной путь, если структура иная
if (!raw) {
  for (const v of Object.values(j)) {
    if (typeof v === 'string' && v.length > raw.length) raw = v;
  }
}
if (!raw) throw new Error('Пустой ответ. Поля: ' + Object.keys(j).join(', '));

// снимаем рассуждения Qwen3
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '');
raw = raw.replace(/<think>[\s\S]*/gi, '');

raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s === -1) throw new Error('В ответе нет JSON: ' + raw.slice(0, 200));

let map;
try { map = JSON.parse(raw.slice(s, e + 1)); }
catch (err) { map = JSON.parse(raw.slice(s, e + 1).replace(/,\s*([}\]])/g, '$1')); }

// отбрасываем поля, которых нет в схеме — защита от выдумок модели
const clean = {};
for (const [col, field] of Object.entries(map)) {
  if (ALLOWED.indexOf(field) !== -1) clean[col] = field;
}
if (Object.keys(clean).length === 0) {
  throw new Error('Маппинг пустой. Модель вернула: ' + JSON.stringify(map));
}

const rows = $(PREV_NODE).first().json.rows;
const out = [];

for (const r of rows) {
  const o = { source_sheet: SHEET };
  for (const [col, field] of Object.entries(clean)) {
    const v = r[col];
    if (v === undefined || v === null || String(v).trim() === '') o[field] = null;
    else o[field] = String(v).trim();
  }
  if (!o.specialty) o.specialty = 'Аналитик BI';
  if (o[REQUIRED]) out.push({ json: o });
}

if (out.length === 0) {
  throw new Error('Ни одной строки не разложилось. Маппинг: ' + JSON.stringify(clean));
}
return out;

